/*!40000 ALTER TABLE `ai_tool` DISABLE KEYS */;
INSERT INTO `ai_tool` VALUES (1,'getPaymentSummary','查询客户回款汇总统计。支持按月份统计回款总金额、回款笔数，可按客户名称过滤。示例问句：\"本月回款情况\"、\"上个月回款了多少\"、\"XX客户今年回款\"','[{\"name\":\"month\",\"type\":\"string\",\"required\":false,\"desc\":\"月份，格式yyyy-MM，如2026-09；用户说本月/上个月时换算\"},{\"name\":\"customerName\",\"type\":\"string\",\"required\":false,\"desc\":\"客户名称关键词，模糊匹配\"}]','sql','SELECT DATE_FORMAT(pr.payment_date, \'%Y-%m\') AS 月份, c.customer_name AS 客户名称, COUNT(*) AS 回款笔数, SUM(pr.this_amount) AS 回款金额 FROM mk_payment_record pr LEFT JOIN mk_customer c ON pr.customer_id = c.customer_id WHERE 1=1 AND (:month IS NULL OR DATE_FORMAT(pr.payment_date, \'%Y-%m\') = :month) AND (:customerName IS NULL OR c.customer_name LIKE CONCAT(\'%\', :customerName, \'%\')) GROUP BY DATE_FORMAT(pr.payment_date, \'%Y-%m\'), c.customer_name ORDER BY 回款金额 DESC LIMIT 100',NULL,'0','','2026-09-18 11:29:03','','2026-09-18 11:29:03'),(2,'getOverduePaymentList','查询逾期未回款明细。返回逾期客户、逾期金额、计划回款日期。示例问句：\"哪些客户逾期了\"、\"逾期回款明细\"、\"逾期超30天的客户\"','[{\"name\":\"customerName\",\"type\":\"string\",\"required\":false,\"desc\":\"客户名称关键词，模糊匹配\"}]','sql','SELECT c.customer_name AS 客户名称, ct.contract_no AS 合同编号, pp.period_no AS 期数, pp.plan_amount AS 计划回款金额, pp.actual_amount AS 已回款金额, (pp.plan_amount - pp.actual_amount) AS 未回款金额, pp.plan_date AS 计划回款日期, DATEDIFF(CURDATE(), pp.plan_date) AS 逾期天数 FROM mk_payment_plan pp LEFT JOIN mk_customer c ON pp.customer_id = c.customer_id LEFT JOIN mk_contract ct ON pp.contract_id = ct.contract_id WHERE pp.overdue_flag = \'1\' AND (:customerName IS NULL OR c.customer_name LIKE CONCAT(\'%\', :customerName, \'%\')) ORDER BY 逾期天数 DESC LIMIT 100',NULL,'0','','2026-09-18 11:29:03','','2026-09-18 11:29:03'),(3,'getStockAnalysis','查询库存分析。返回物料库存数量、锁定数量、可用数量，库存量排序。示例问句：\"库存分析前10\"、\"库存最多的物料\"、\"XX物料还有多少库存\"','[{\"name\":\"materialName\",\"type\":\"string\",\"required\":false,\"desc\":\"物料名称关键词，模糊匹配\"},{\"name\":\"topN\",\"type\":\"number\",\"required\":false,\"desc\":\"返回条数，默认10，最大100\"}]','sql','SELECT m.material_name AS 物料名称, m.spec_model AS 规格型号, w.warehouse_name AS 仓库, SUM(i.qty) AS 库存数量, SUM(i.lock_qty) AS 锁定数量, (SUM(i.qty) - SUM(i.lock_qty)) AS 可用数量 FROM wms_inventory i LEFT JOIN wms_material m ON i.material_id = m.material_id LEFT JOIN wms_warehouse w ON i.warehouse_id = w.warehouse_id WHERE i.del_flag = \'0\' AND (:materialName IS NULL OR m.material_name LIKE CONCAT(\'%\', :materialName, \'%\')) GROUP BY m.material_name, m.spec_model, w.warehouse_name ORDER BY 库存数量 DESC LIMIT :topN',NULL,'0','','2026-09-18 11:29:03','','2026-09-18 11:29:03'),(4,'getWorkOrderStatusDistribution','查询生产工单数量按状态分布统计（全量工单按状态聚合）。仅回答\"工单状态分布/各状态多少单\"这类整体统计问题；查询单台指定设备或指定工单的明细记录不属于本工具。示例问句：\"本月工单数量按状态分布如何\"、\"工单状态分布\"、\"各状态工单有多少\"','[{\"name\":\"month\",\"type\":\"string\",\"required\":false,\"desc\":\"月份，格式yyyy-MM，如2026-09；用户说本月/上个月时换算，未提及时传null\"}]','sql','SELECT CASE w.status WHEN \'0\' THEN \'草稿\' WHEN \'1\' THEN \'已下达\' WHEN \'2\' THEN \'执行中\' WHEN \'3\' THEN \'已完工\' WHEN \'4\' THEN \'已关闭\' WHEN \'5\' THEN \'已暂停\' WHEN \'6\' THEN \'已作废\' ELSE w.status END AS 状态, COUNT(*) AS 工单数量 FROM mms_work_order w WHERE (:month IS NULL OR DATE_FORMAT(w.create_time, \'%Y-%m\') = :month) GROUP BY w.status ORDER BY 工单数量 DESC LIMIT 100',NULL,'0','admin','2026-09-18 19:33:00','','2026-09-18 21:29:43'),(5,'getSupplierSupplyRanking','查询供应商供货金额排名（基于采购订单明细金额汇总）。返回供应商名称、订单数、供货金额，按金额降序。示例问句：\"各供应商的供货金额排名\"、\"供应商供货金额排名\"、\"哪些供应商供货最多\"、\"供货金额前5的供应商\"','[{\"name\":\"topN\",\"type\":\"number\",\"required\":false,\"desc\":\"返回条数，默认10，最大100；用户说前5/前10时换算\"}]','sql','SELECT po.supplier_name AS 供应商名称, COUNT(DISTINCT po.order_id) AS 订单数, SUM(pod.amount) AS 供货金额 FROM pms_purchase_order po JOIN pms_purchase_order_detail pod ON po.order_id = pod.order_id AND pod.del_flag = \'0\' WHERE po.del_flag = \'0\' GROUP BY po.supplier_name ORDER BY 供货金额 DESC LIMIT :topN',NULL,'0','admin','2026-09-18 19:33:00','','2026-09-18 19:33:00'),(6,'getFaultyEquipmentTop','查询故障/报修次数最多的设备排名统计（多台设备聚合排名，不针对单一指定设备）。仅回答\"哪些设备故障最多/故障排名\"这类整体排名问题；查询单台指定设备（给出设备编号或名称）是否有工单/报修记录的问题不属于本工具。示例问句：\"故障最多的前5台设备\"、\"哪些设备故障最多\"、\"设备故障排名\"','[{\"name\":\"topN\",\"type\":\"number\",\"required\":false,\"desc\":\"返回条数，默认5，最大100\"},{\"name\":\"month\",\"type\":\"string\",\"required\":false,\"desc\":\"月份，格式yyyy-MM；未提及时传null\"}]','sql','SELECT w.equipment_name AS 设备名称, COUNT(*) AS 故障次数 FROM dms_work_order w WHERE w.del_flag = \'0\' AND w.equipment_name IS NOT NULL AND w.equipment_name != \'\' AND (:month IS NULL OR DATE_FORMAT(w.report_time, \'%Y-%m\') = :month) GROUP BY w.equipment_name ORDER BY 故障次数 DESC LIMIT :topN',NULL,'0','admin','2026-09-18 19:33:00','','2026-09-18 21:29:43'),(7,'getExpiringBatchAdvice','查询临期批次清单（FEFO出库顺序）。返回批次号、物料、批次数量、到期日期、剩余天数、状态。示例问句：\"哪些批次快到期\"、\"临期批次有哪些\"、\"过期批次清单\"','[{\"name\":\"days\",\"type\":\"number\",\"desc\":\"临期天数阈值，默认30天\"}]','sql','SELECT b.batch_code AS 批次号, m.material_name AS 物料, b.qty AS 批次数量, b.qty_unit AS 单位, b.expire_date AS 到期日期, DATEDIFF(b.expire_date, CURDATE()) AS 剩余天数, CASE b.batch_status WHEN \'0\' THEN \'待检\' WHEN \'1\' THEN \'合格\' WHEN \'2\' THEN \'冻结\' WHEN \'3\' THEN \'报废\' ELSE b.batch_status END AS 状态 FROM food_batch b LEFT JOIN wms_material m ON b.material_id = m.material_id WHERE b.expire_date IS NOT NULL AND b.del_flag = \'0\' AND DATEDIFF(b.expire_date, CURDATE()) <= IFNULL(:days, 30) ORDER BY b.expire_date ASC LIMIT 50','food:batch:list','0','admin','2026-10-14 19:57:23','','2026-10-14 20:07:30'),(8,'getLossRateAnomaly','查询损耗率超阈值的生产工单（损耗率=(计划量-合格量)/计划量）。返回工单号、产品、计划量、合格量、不良量、损耗率。示例问句：\"哪些工单损耗异常\"、\"损耗率超过10%的工单\"','[{\"name\":\"threshold\",\"type\":\"number\",\"desc\":\"损耗率阈值百分比，默认10\"}]','sql','SELECT work_order_no AS 工单号, product_name AS 产品, plan_qty AS 计划量, qualified_qty AS 合格量, defect_qty AS 不良量, ROUND((plan_qty - IFNULL(qualified_qty, 0)) / plan_qty * 100, 2) AS 损耗率, status AS 工单状态 FROM mms_work_order WHERE plan_qty > 0 AND del_flag = \'0\' AND (plan_qty - IFNULL(qualified_qty, 0)) / plan_qty * 100 >= IFNULL(:threshold, 10) ORDER BY 损耗率 DESC LIMIT 30','mms:workorder:list','0','admin','2026-10-14 19:57:23','','2026-10-14 19:57:23');
/*!40000 ALTER TABLE `ai_tool` ENABLE KEYS */;
UNLOCK TABLES;

