  `deposit_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '保证金类型（字典 bid_deposit_type）',
  `pay_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '1' COMMENT '缴纳形式（字典 bid_pay_type）',
  `amount` decimal(14,2) NOT NULL COMMENT '缴纳金额（元）',
  `refund_amount` decimal(15,2) DEFAULT NULL COMMENT '已退金额',
  `pay_time` datetime DEFAULT NULL COMMENT '缴纳时间',
  `expect_refund_time` datetime DEFAULT NULL COMMENT '应退回时间',
  `actual_refund_time` datetime DEFAULT NULL COMMENT '实际退回时间',
  `refund_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '退回状态（字典 bid_refund_status）',
  `voucher_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '缴纳凭证附件',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门ID',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`deposit_id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_refund_status` (`refund_status`),
