  `partner_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单位名称',
  `partner_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型 SUPPLIER/CUSTOMER/BOTH',
  `source_module` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源模块 wms/mk',
  `source_id` bigint DEFAULT NULL COMMENT '来源主数据ID（wms_supplier.supplier_id 或 mk_customer.customer_id）',
