  KEY `idx_partner_type` (`partner_type`,`status`),
  KEY `idx_partner_name` (`partner_name`),
  KEY `idx_partner_dept` (`dept_id`),
  KEY `idx_partner_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='财务往来单位表';
