  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'CONFIRMED' COMMENT '状态 DRAFT待确认/CONFIRMED已确认/VOID已作废',
