--
-- Table structure for table `fin_voucher`
--

DROP TABLE IF EXISTS `fin_voucher`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fin_voucher` (
  `voucher_id` bigint NOT NULL AUTO_INCREMENT COMMENT '凭证ID',
  `voucher_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '凭证号',
  `company_id` bigint DEFAULT NULL COMMENT '预留账套ID',
  `voucher_date` date NOT NULL COMMENT '凭证日期',
  `period` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会计期间 YYYYMM（由 voucher_date 派生，不允许手填）',
  `voucher_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'MANUAL' COMMENT '类型 MANUAL手工/AUTO自动/CANCEL红字冲销',
  `source_module` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'manual' COMMENT '来源模块 pms/mk/wms/hr/manual',
  `source_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源单据类型 invoice/shipment/outbound/payroll',
  `source_id` bigint NOT NULL DEFAULT '0' COMMENT '来源单据ID（手工为0）',
  `source_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源单据号（冗余，便于人工排查）',
  `rule_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '命中的记账规则键（手工录入为空串，保证空串参与唯一索引）',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门ID（BizDeptFillAspect 自动填充）',
  `user_id` bigint DEFAULT NULL COMMENT '制单人ID（对应 user_id 列，DataScope userAlias 用）',
  `total_amount` decimal(14,2) DEFAULT '0.00' COMMENT '价税合计（借方合计）',
  `entry_count` int DEFAULT '0' COMMENT '分录行数',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'DRAFT' COMMENT '状态 DRAFT草稿/AUDITED已审核/POSTED已记账/CANCELLED已冲销',
  `attach_count` int DEFAULT '0' COMMENT '附件数',
  `audit_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核意见',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`voucher_id`),
  UNIQUE KEY `uk_voucher_no` (`voucher_no`),
  UNIQUE KEY `uk_source` (`source_module`,`source_type`,`source_id`,`rule_key`,`del_flag`),
  KEY `idx_period` (`period`,`status`),
  KEY `idx_source` (`source_module`,`source_type`,`source_id`),
  KEY `idx_voucher_date` (`voucher_date`),
  KEY `idx_voucher_dept` (`dept_id`),
  KEY `idx_voucher_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='记账凭证主表';
/*!40101 SET character_set_client = @saved_cs_client */;

