  `period` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会计期间（冗余自凭证，加速账簿汇总）',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门ID（随凭证继承）',
  `account_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会计科目编码',
