--
-- Table structure for table `mk_opportunity`
--

DROP TABLE IF EXISTS `mk_opportunity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mk_opportunity` (
  `opportunity_id` bigint NOT NULL AUTO_INCREMENT COMMENT '商机ID',
  `opportunity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商机编号',
  `opportunity_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商机名称',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `contact_id` bigint DEFAULT NULL COMMENT '主要联系人ID',
  `lead_id` bigint DEFAULT NULL COMMENT '来源线索ID',
  `opportunity_source` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '商机来源（字典）',
  `expected_amount` decimal(14,2) NOT NULL COMMENT '预计金额',
  `expected_date` date NOT NULL COMMENT '预计成交日期',
  `stage_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'stage1' COMMENT '销售阶段编码',
