INSERT INTO `sys_role` VALUES (1,'超级管理员','admin',1,'system',NULL,'1',1,1,'0','0','admin','2026-07-13 11:25:52','',NULL,'超级管理员'),(2,'普通角色','common',2,'system',NULL,'2',1,1,'0','2','admin','2026-07-13 11:25:52','',NULL,'普通角色'),(100,'普通员工','common_user',3,'system',NULL,'5',1,1,'0','0','admin','2026-07-13 11:25:54','admin','2026-09-10 11:15:30','普通员工角色：所有业务模块只读权限（可查看菜单、查询数据、导出数据），不可新增/修改/删除'),(101,'财务人员','finance',4,'system','fin','3',1,1,'1','0','admin','2026-07-13 11:25:54','',NULL,'财务人员角色模板：财务相关菜单权限 [模块停用:fin]'),(102,'部门负责人','dept_leader',5,'system',NULL,'4',1,1,'0','0','admin','2026-07-13 11:25:54','',NULL,'部门负责人角色模板：部门管理、人员查看'),(103,'业务经理','business_manager',6,'system',NULL,'2',1,1,'0','0','admin','2026-07-13 11:25:54','admin','2026-08-04 16:44:17','业务经理角色模板：业务相关权限'),(104,'总经理','general_manager',1,'system',NULL,'1',0,0,'0','0','admin','2026-07-24 08:32:17','admin','2026-07-26 23:14:53','总经理（决策层）：全系统只读访问，DMS模块含设备台账只读、工单列表查询导出、PM计划只读、备件库存只读、巡检点检只读、库存流水只读、数据看板、设备大屏'),(110,'安全员','safety_officer',50,'safety','safety','3',1,1,'1','0','admin','2026-08-12 11:13:33','',NULL,'安全生产管理-安全员：日常巡检、隐患上报整改、到期提醒处理。权限：查询/新增/编辑/整改，不含删除/审批/导出'),(111,'安全主管','safety_manager',51,'safety','safety','1',1,1,'1','0','admin','2026-08-12 11:13:33','',NULL,'安全生产管理-安全主管：安全管理工作统筹、隐患审批、数据分析。权限：全部安全模块权限'),(120,'质量检验员','qms_inspector',60,'qms','qms','4',1,1,'0','0','admin','2026-08-15 16:22:19','',NULL,'检验员角色：检验任务查看与录入、NCR登记、数据查看'),(121,'质量工程师','qms_engineer',61,'qms','qms','3',1,1,'0','0','admin','2026-08-15 16:22:19','',NULL,'工程师角色：不合格品评审、CAPA管理、供应商质量、客诉处理、追溯管理'),(122,'质量主管','qms_manager',62,'qms','qms','2',1,1,'0','0','admin','2026-08-15 16:22:19','',NULL,'质量主管角色：全部质量管理权限，含NCR审批、质量目标、体系管理、报表导出'),(123,'质量总监','qms_director',63,'qms','qms','1',1,1,'0','0','admin','2026-08-15 16:27:30','',NULL,'质量总监角色：全公司质量决策，全部数据范围，含质量目标制定、管理评审主导、NCR终审'),(124,'供应商质量工程师','qms_sqe',64,'qms','qms','3',1,1,'0','0','admin','2026-08-15 16:27:30','',NULL,'SQE角色：供应商质量评价、推送日志、客诉8D回复、来料检验标准维护'),(125,'质量体系专员','qms_doc_admin',65,'qms','qms','3',1,1,'0','0','admin','2026-08-15 16:27:30','',NULL,'体系专员角色：质量文档管理、内部审核、管理评审组织、编码规则维护'),(126,'质量数据分析员','qms_analyst',66,'qms','qms','1',1,1,'0','0','admin','2026-08-15 16:27:30','',NULL,'数据分析员角色：质量报表查看导出、质量看板、质量目标监控、追溯查询'),(200,'设备管理员','dms_manager',10,'dms','dms','1',1,1,'1','0','admin','2026-07-26 22:36:13','',NULL,'DMS设备管理模块负责人：设备台账增删改查导、PM计划增删改查、备件出入库全管理、工单派工/改派/验收/驳回/撤销、巡检点检全管理、采集配置全管理、数据看板、维修知识库、AI配置'),(201,'维修工程师','dms_engineer',11,'dms','dms','4',1,1,'1','0','admin','2026-07-26 22:36:13','',NULL,'一线维修人员：工单接单/处理/完工、备件领用出库、设备台账只读、PM计划只读、点检任务执行、库存台账只读、维修知识库查询、数据看板'),(202,'车间操作员','dms_operator',12,'dms','dms','3',1,1,'1','0','admin','2026-07-26 22:36:13','',NULL,'一线操作工：工单报修新增、撤销自己的报修、点检任务执行、运行数据人工录入、设备台账只读、数据看板'),(203,'车间主管','dms_supervisor',13,'dms','dms','4',1,1,'1','0','admin','2026-07-26 22:36:13','',NULL,'车间负责人：工单派工/改派/验收/驳回/撤销、工单新增修改导出、设备台账只读、PM计划只读、备件库存只读、备件预警只读、巡检点检只读、数据看板、设备大屏'),(300,'营销总监','mk_director',20,'mk','mk','1',1,1,'1','0','admin','2026-07-26 23:01:40','',NULL,'营销管理模块负责人：客户/线索/商机/活动/合同/订单/回款/发票/退货全模块增删改查导审批、客户分配与公海审批、线索分配与公海审批、合同审批/续签/变更、退货审批/退款、回款确认、发票开票/作废、阶段配置、编号规则、数据看板 [模块停用:mk]'),(301,'销售经理','mk_sales_manager',21,'mk','mk','4',1,1,'1','0','admin','2026-07-26 23:01:40','',NULL,'销售团队负责人：客户/联系人/互动/标签增删改查导、线索增删改查导+公海领取(不可审批)、商机增删改查导、活动全管理+参与人管理+转线索、合同增删改查导+续签+变更(不可审批)、订单增删改查导+发货+确认+签收(不可取消)、退货新增+查询+导出(不可审批/退款)、回款增删改查(不可确认)、发票查看、阶段查看、数据看板 [模块停用:mk]'),(302,'销售代表','mk_sales',22,'mk','mk','5',1,1,'1','0','admin','2026-07-26 23:01:40','',NULL,'一线销售人员：客户查询/新增/修改/公海领取、联系人查询/新增/修改、互动查询/新增/修改、标签查询、线索查询/新增/修改+公海领取(不可审批)、商机查询/新增/修改、活动查询、参与人查询、合同查询/新增、订单查询/新增、回款查询/新增、退货查询、发票查询、数据看板 [模块停用:mk]'),(303,'财务专员','mk_finance',23,'mk','mk','1',1,1,'1','0','admin','2026-07-26 23:01:40','',NULL,'财务人员：发票全管理(开票/作废/增删改查导)、回款查询+确认、合同查询、订单查询+导出、退货查询+导出+退款、数据看板 [模块停用:mk]'),(304,'市场专员','mk_marketer',24,'mk','mk','1',1,1,'1','0','admin','2026-07-26 23:01:40','',NULL,'市场活动人员：活动全管理(新增/修改/删除/导出/状态变更/复盘/复制)、活动参与人全管理+转线索、客户/线索/商机/联系人查看、数据看板 [模块停用:mk]'),(400,'仓库主管','wms_manager',30,'wms','wms','1',1,1,'0','0','admin','2026-07-26 23:33:49','',NULL,'仓储管理模块负责人：物料/供应商/仓库全管理、入库全管理(提交/收货/上架)、出库全管理(提交/拣货)、波次管理、移库全管理(审批/执行/作废)、盘点全管理(开始/提交/录入/审批/作废)、库存/流水/预警全管理、统计报表'),(401,'入库管理员','wms_inbound',31,'wms','wms','1',1,1,'0','0','admin','2026-07-26 23:33:49','',NULL,'入库业务专员：入库单增删改查导+提交/收货/上架作业、物料/供应商/仓库只读、库存查询/流水查看、统计报表'),(402,'出库管理员','wms_outbound',32,'wms','wms','1',1,1,'0','0','admin','2026-07-26 23:33:49','',NULL,'出库业务专员：出库单增删改查导+提交/拣货作业、扫码复核、波次管理、物料/供应商/仓库只读、库存查询/流水查看、统计报表'),(403,'盘点员','wms_stocktake',33,'wms','wms','1',1,1,'0','0','admin','2026-07-26 23:33:49','',NULL,'盘点作业人员：盘点单增删改查+开始/提交审批/明细录入/批量录入/批量导入/导出模板(不可审批/作废)、仓库只读、库存查询/流水查看、统计报表'),(404,'库存查询员','wms_viewer',34,'wms','wms','1',1,1,'0','0','admin','2026-07-26 23:33:49','',NULL,'库存只读人员：物料/供应商/仓库只读、入库/出库/移库/盘点只读、库存查询/流水查看/预警查询导出、统计报表'),(500,'采购总监','pms_director',40,'pms','pms','1',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'采购管理模块负责人：全模块增删改查导审批、供应商全管理、采购看板、编号规则、企业查询配置 [模块停用:pms]'),(501,'采购经理','pms_manager',41,'pms','pms','4',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'采购团队负责人：采购计划/申请/询比价/合同/订单全管理+审批、收货退货发票增删改查(不可审核)、供应商只读、采购看板 [模块停用:pms]'),(502,'采购员','pms_buyer',42,'pms','pms','5',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'一线采购人员：采购计划/申请/询比价/合同/订单 查询+新增+修改+导出(不可删除/审批)、收货退货查询+新增、供应商只读、采购看板 [模块停用:pms]'),(503,'收货专员','pms_receiver',43,'pms','pms','3',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'收货验收专员：收货验收全管理(含审核)、退货管理全管理(含审批)、采购订单只读、供应商信息只读、采购看板 [模块停用:pms]'),(504,'供应商管理员','pms_supplier_mgr',44,'pms','pms','1',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'供应商管理员：供应商信息/资质/供货清单/评价全管理(含审核/导入)、采购看板 [模块停用:pms]'),(505,'采购财务','pms_finance',45,'pms','pms','1',1,1,'1','0','admin','2026-08-02 15:55:56','',NULL,'采购财务专员：发票结算全管理(含审核/付款)、采购订单/收货/退货只读、采购看板 [模块停用:pms]'),(600,'生产总监','mms_director',50,'mms','mms','1',1,1,'0','0','admin','2026-08-25 20:28:48','',NULL,'生产管控模块负责人：全模块增删改查导审批、工单全生命周期管理、生产看板'),(601,'计划员','mms_planner',51,'mms','mms','1',1,1,'0','0','admin','2026-08-25 20:28:49','',NULL,'生产计划人员：需求管理、主生产计划、排产管理、齐套检查全管理；基础数据只读'),(602,'车间主任','mms_workshop_manager',52,'mms','mms','4',1,1,'0','0','admin','2026-08-25 20:28:49','',NULL,'车间负责人：工单管理全权限(含状态变更)、派工调度全权限、报工审核、异常处置'),(603,'操作工','mms_operator',53,'mms','mms','5',1,1,'0','0','admin','2026-08-25 20:28:49','',NULL,'一线操作人员：派工接收开工完工、报工录入、异常上报、领料确认、退料录入、完工入库'),(610,'财务经理','fin_manager',70,'fin','fin','1',1,1,'1','0','admin','2026-10-08 20:34:44','',NULL,'财务模块全权限：凭证录入+审核+反审核+结账+期间解锁。制单与审核可同人（中小企业现实约束），但反审核需留痕'),(611,'会计','fin_accountant',71,'fin','fin','4',1,1,'1','0','admin','2026-10-08 20:34:44','',NULL,'财务会计：可录入/修改凭证、管理往来与应收应付、查看报表。【禁止】凭证审核、反审核、期末结账、期间解锁'),(612,'出纳','fin_cashier',72,'fin','fin','5',1,1,'1','0','admin','2026-10-08 20:34:44','',NULL,'财务出纳：可登记收付款、办理银行对账、开票。【禁止】凭证录入与修改（钱账分离）'),(700,'人事专员','hr_manager',7,'system',NULL,'1',1,1,'0','0','admin','2026-10-14 19:57:23','',NULL,'P3人力轻量启用配套角色'),(701,'产品设计主管','pdm_manager',100,'pdm','pdm','1',1,1,'0','0','admin','2026-10-20 16:41:38','',NULL,'产品设计模块全部管理权限'),(702,'设计工程师','pdm_engineer',101,'pdm','pdm','4',1,1,'0','0','admin','2026-10-20 16:41:38','',NULL,'产品设计业务操作权限（数据范围限本人）'),(703,'设计资料查看','pdm_viewer',102,'pdm','pdm','1',1,1,'0','0','admin','2026-10-20 16:41:38','',NULL,'产品设计只读查看权限');
